import {
  IHikingRepairKitDTO,
  IHikingRepairKitUsageDTO,
} from '../@types/DTO/hikingRepairKit.dto.types';
import { IHikingRepairKit, IHikingRepairKitUsage } from '../@types/hikingRepairKit.types';

export const mapHikingRepairKit = (backData: IHikingRepairKitDTO): IHikingRepairKit => {
  return {
    id: +backData.id,
    name: backData.name,
    comment: backData.comment,
    create: {
      date: new Date(backData.created_at),
      user: {
        id: +backData.creator_id,
        name: backData.creator_name,
        surname: backData.creator_surname,
        photo: backData.creator_photo,
      },
    },
    update: backData.updated_at
      ? {
          date: new Date(backData.updated_at),
          user: {
            id: +backData.updater_id,
            name: backData.updater_name,
            surname: backData.updater_surname,
            photo: backData.updater_photo,
          },
        }
      : null,
    weight: +backData.weight,
    assignee: backData.id_assignee
      ? {
          id: +backData.id_assignee,
          name: backData.assignee_name,
          surname: backData.assignee_surname,
          photo: backData.assignee_photo,
        }
      : null,
  };
};

export const mapHikingRepairKitUsage = (
  backData: IHikingRepairKitUsageDTO,
): IHikingRepairKitUsage => {
  return {
    id: +backData.id,
    comment: backData.comment,
    id_hiking_repair_kit: +backData.id_hiking_repair_kit,
    date: new Date(backData.date),
    create: {
      date: new Date(backData.created_at),
      user: {
        id: +backData.creator_id,
        name: backData.creator_name,
        surname: backData.creator_surname,
        photo: backData.creator_photo,
      },
    },
    user: backData.id_user
      ? {
          id: +backData.id_user,
          name: backData.user_name,
          surname: backData.user_surname,
          photo: backData.user_photo,
        }
      : null,
  };
};
